+	switch (cmd) {
+	case ELE_SESSION_CLOSE_REQ:
+		if (tx_msg_sz < ELE_SESSION_CLOSE_REQ_SZ ||
+		    msg->data[0] != dev_ctx->sess_hdl)
+			return -EINVAL;
+		return 0;
